use vstd::prelude::*;

verus! {

fn array_split(a: Vec<i32>) -> (left: Vec<i32>, right: Vec<i32>)
    ensures
        // lengths add up
        left@.len() + right@.len() == a@.len(),
        // concatenation preserves order and contents
        left@ + right@ == a@,
        // if n > 1, then both parts are strictly shorter than a
        a@.len() > 1 ==> (left@.len() < a@.len() && right@.len() < a@.len()),
{
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left ++ right == a (preserves order)
    // - if n > 1, then 0 < split < n so both parts are strictly shorter than a
    let split = if n <= 1 { n } else { n / 2 }; // for n>=2, n/2 is in [1, n-1]

    // Facts about the split point (used to justify the postconditions)
    assert(split <= n);
    if n > 1 {
        assert(split > 0);      // since split = n/2 and n>=2
        assert(split < n);      // since n/2 <= n-1 for n>=2
    }

    let left = a[..split].to_vec();
    let right = a[split..].to_vec();

    // Relate slices to the original sequence
    assert(left@ == a@.subrange(0, split as int));
    assert(right@ == a@.subrange(split as int, n as int));

    // Show concatenation equals the original
    assert(left@ + right@ == a@) by {
        assert(a@.subrange(0, split as int) + a@.subrange(split as int, n as int) == a@);
    }

    (left, right)
}

} // verus!

